// @whimtex-effect Samples/Gradient Map
// @control(_Opacity)
// @group
// @formerlyserializedas(_Amount)
// @param hidden float _Opacity = 0.33 [0 .. 1] // Blend between the original colors and the gradient map.
// @param gradient _Gradient = (0, 0, 0, 1) -> (1, 1, 1, 1) // Colors from shadows to highlights.
// @param curve _Mapping = keys((0, 0, -0.0391975343, -0.0391975343, 0, 0.0607424043, 0), (1, 1, 0.691987038, 0.691987038, 0.11698544, 0, 0)) // Remap brightness before sampling the gradient; the default is unchanged.
// @param bool _Reverse = false // Map highlights to the beginning of the gradient instead of shadows.
// @endgroup



#ifndef WHIMTEX_HDR_COLOR_INCLUDED
#define WHIMTEX_HDR_COLOR_INCLUDED
float3 SpriteEncode(float3 color)
{
    float3 value = abs(color);
    return sign(color) * lerp(value * 12.92, 1.055 * pow(value, 1.0 / 2.4) - .055, step(.0031308, value));
}
float3 SpriteDecode(float3 color)
{
    float3 value = abs(color);
    return sign(color) * lerp(value / 12.92, pow((value + .055) / 1.055, 2.4), step(.04045, value));
}
#endif


float4 ApplyFX(float2 uv, float4 color)
{
    float luminance = saturate(dot(max(color.rgb, 0.0), float3(0.2126, 0.7152, 0.0722)));
    float brightness = SpriteEncode(float3(luminance, luminance, luminance)).r;
    float t = _Reverse > 0.5 ? 1.0 - brightness : brightness;
    float4 mapped = _Gradient_Sample(_Mapping_Sample(t));
	return float4(lerp(color.rgb, mapped.rgb, saturate(_Opacity)), color.a);
}

// @whimtex-effect Samples/Master Tint
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @param color _Tint = (1, 1, 1, 1)

float4 ApplyFX(float2 uv,float4 color){return float4(color.rgb*_Tint.rgb,color.a*_Opacity*_Tint.a);}

// @whimtex-effect Samples/Hot Solar Limb
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @param float _Radius = 0.32 [0.1 .. 0.38]
// @param float _Width = 0.014 [0.002 .. 0.035]
// @param float _RimPower = 1.5 [0.3 .. 6]
// @param float _Fresnel = 0.7 [0 .. 1]

float4 ApplyFX(float2 uv,float4 color){
    float r=length(uv-.5);float d=abs(r-_Radius);
    float z=sqrt(saturate(1-pow(r/_Radius,2)));
    float f=pow(1-z,_RimPower)*(1-smoothstep(_Radius,_Radius+.003,r));
    float a=max(exp(-pow(d/_Width,2)),f*_Fresnel);
    return float4(1,.67,.18,a*_Opacity);
}

// @whimtex-effect Samples/Spherize
// @group(Spherize Mode; _Mode)
// @param hidden enum _Mode = 1 { Classic: 0, Sphere: 1 } // Classic is the current unbounded radial distortion. Sphere wraps the image over a sphere and clips outside its circular edge.
// @param float _Strength = 1 [~-1 .. ~1]
// @param transform2D _Area = (0.5, 0.5, 0.64, 0.64, 0)
// @endgroup


float4 ApplyFX(float2 uv, float4 color)
{
    float2 p = (_Area_ToLocal(uv) - 0.5) * 2.0;
    float4 result = color;

    if (_Mode < 0.5)
    {
        if (_Strength != 0)
        {
            float exponent = exp2(_Strength);
            // The epsilon only protects the center; the radius is not limited to the frame.
            float scale = pow(max(dot(p, p), 1e-12), 0.5 * (exponent - 1.0));
            result = SampleInput(_Area_ToInput(0.5 + p * scale * 0.5));
        }
    }
    else
    {
        float radius = length(p);
        float clampedRadius = saturate(radius);
        // A sphere maps the disk to its angular surface coordinates. Positive values bulge;
        // negative values use the inverse mapping and pinch toward the center.
        float sphericalRadius = _Strength >= 0.0
            ? asin(clampedRadius) * 0.6366197723675814
            : sin(clampedRadius * 1.5707963267948966);
        float strength = abs(_Strength);
        float sampleRadius = lerp(radius, sphericalRadius, min(strength, 1.0));
        float excessStrength = max(strength - 1.0, 0.0);
        // Beyond one, continue strengthening smoothly without clamping the soft UI range.
        if (_Strength >= 0.0)
            sampleRadius *= exp2(-excessStrength * (1.0 - sampleRadius));
        else
            sampleRadius = 1.0 - (1.0 - sampleRadius) * exp2(-excessStrength * sampleRadius);
        float radialScale = sampleRadius / max(radius, 1e-6);
        result = SampleInput(_Area_ToInput(0.5 + p * radialScale * 0.5));

        // Keep a crisp circular silhouette with a sub-pixel antialiased edge.
        float edgeWidth = max(fwidth(radius), 1e-4);
        result.a *= 1.0 - smoothstep(1.0 - edgeWidth, 1.0 + edgeWidth, radius);
    }

    return result;
}

// @whimtex-effect Samples/Stellar Granulation
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @param float _Radius = 0.32 [0.1 .. 0.38]
// @param float _Contrast = 2 [0.5 .. 4]
// @param float _Fresnel = 0.9 [0 .. 1]
// @param float _RimPower = 1.4 [0.3 .. 6]

float4 ApplyFX(float2 uv,float4 color){
    float2 p=(uv-.5)/_Radius;float r=length(p);
    float z=sqrt(saturate(1-dot(p,p)));
    float n=saturate(color.r);
    float macro=SampleInput(saturate(.5+(uv-.5)*.16)).r;
    float heat=saturate((n-.5)*_Contrast+.5+(macro-.5)*.7);
    float3 ember=float3(.22,.012,.0008);
    float3 orange=float3(.92,.10,.002);
    float3 hot=float3(1,.43,.035);
    float3 col=lerp(ember,orange,smoothstep(.05,.6,heat));
    col=lerp(col,hot,pow(heat,3));
    col*=.52+.24*z;
    float fresnel=pow(1-z,_RimPower)*_Fresnel;
    col=lerp(col,float3(1,.58,.12),fresnel);
    return float4(saturate(col),(1-smoothstep(.995,1.005,r))*_Opacity);
}

// @whimtex-effect Samples/Solar Corona
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @param float _Radius = 0.3275 [0.1 .. 0.38]
// @param float _Reach = 0.0677 [0.02 .. 0.16]
// @param float _Turbulence = 0.148 [0 .. 1]

float4 ApplyFX(float2 uv,float4 color){
    float r=length(uv-.5);float a=atan2(uv.y-.5,uv.x-.5);
    float n=color.r;
    float spoke=.5+.25*sin(a*47+sin(a*13)*2)+.25*sin(a*91+1.3);
    float reach=_Reach*lerp(1,.65+.35*spoke,_Turbulence);
    float outside=max(r-_Radius,0);
    float glow=exp(-pow(outside/max(reach*.48,.001),1.25));
    float alpha=glow*lerp(1,.7+.3*n,_Turbulence)*(1-smoothstep(.445,.49,r));
    float3 tint=lerp(float3(1,.49,.06),float3(1,.055,.001),saturate(outside/_Reach));
    return float4(tint,alpha*_Opacity);
}
